JVMTI (Java Virtual Machine Tools Interface) is a native API that allows you to implement custom class transformers for the Java Virtual Machine (JVM). Here are some code examples of JVMTI class transformations in Android:

**Example 1: Logging Class Load Events**
```c
#include <jitviewer/jitviewer.h>

// Structure to hold class load event data
typedef struct {
    uint32_t classIndex;
    uint32_t bytecodeLength;
} ClassLoadEvent structure;

// JVMTI agent implementation
JNIEXPORT jint JNICALL Agent_OnLoad(JavaVM* vm, char* options) {
    // Create a JVMTI environment
    JVMTIEnv* env = (*vm)->GetEnv(vm, JVMTIArchitectureNeutral);
    if (env == NULL) {
        return -1;
    }

    // Set the class load event handler
    env->SetEventNotifier(env, JT_EVENT_CLASS_LOAD);
    env->SetEventCallback(env, classLoadEventCallback);

    return 0;
}

// Event callback function
void JNICALL classLoadEventCallback(JVMTIEnv* env, JNIEnv* jnienv,.jdwpEventHeader* event_header) {
    // Get the class load event data
    ClassLoadEvent structure* event;
    event = (ClassLoadEvent structure*)event_header->event;

    // Log the class load event
    printf("Class loaded: %s (class index: %u, bytecode length: %u)\n",
           event->class_name, event->classIndex, event->bytecodeLength);
}
```
This example demonstrates how to use the JVMTI API to log class load events. The `Agent_OnLoad` function is called by the JVM when the agent is loaded, and it sets up the event notifier and callback function. The `classLoadEventCallback` function is called by the JVM when a class is loaded, and it logs the event to the console.

**Example 2: Modifying Class Bytecode**
```c
#include <jitviewer/jitviewer.h>

// Structure to hold modified class bytecode
typedef struct {
    uint32_t* bytecode;
    uint32_t bytecodeLength;
} ModifiedClassBytecode structure;

// JVMTI agent implementation
JNIEXPORT jint JNICALL Agent_OnLoad(JavaVM* vm, char* options) {
    // Create a JVMTI environment
    JVMTIEnv* env = (*vm)->GetEnv(vm, JVMTIArchitectureNeutral);
    if (env == NULL) {
        return -1;
    }

    // Set the class transform event handler
    env->SetEventNotifier(env, JT_EVENT_CLASS_TRANSFORM);
    env->SetEventCallback(env, classTransformEventCallback);

    return 0;
}

// Event callback function
void JNICALL classTransformEventCallback(JVMTIEnv* env, JNIEnv* jnienv,.jdwpEventHeader* event_header) {
    // Get the class transform event data
    modifiedClassBytecode structure* event;
    event = (modifiedClassBytecode structure*)event_header->event;

    // Modify the class bytecode
    for (uint32_t i = 0; i < event->bytecodeLength; i++) {
        event->bytecode[i] += 1; // Add 1 to each bytecode instruction
    }

    // Replace the original bytecode with the modified bytecode
    env->ModifyBytecodes(env, event->classIndex, event->bytecode, event->bytecodeLength);
