import React, { useState } from 'react';

function TodoList() {
  const [todos, setTodos] = useState([
    { id: 1, name: 'Buy milk', done: false },
    { id: 2, name: 'Walk the dog', done: false },
    { id: 3, name: 'Do laundry', done: false }
  ]);

  const handleAddTodo = (name) => {
    setTodos((prevTodos) => [...prevTodos, { id: prevTodos.length + 1, name, done: false }]);
  };

  const handleToggleTodo = (id) => {
    setTodos((prevTodos) => prevTodos.map((todo) => (todo.id === id ? { ...todo, done: !todo.done } : todo)));
  };

  const handleDeleteTodo = (id) => {
    setTodos((prevTodos) => prevTodos.filter((todo) => todo.id !== id));
  };

  return (
    <div>
      <h1>Todos</h1>
      <form>
        <input type="text" placeholder="New Todo" onChange={(e) => handleAddTodo(e.target.value)} />
        <button type="submit">Add Todo</button>
      </form>
      <ul>
        {todos.map((todo) => (
          <li key={todo.id} style={{ textDecoration: todo.done ? 'line-through' : 'none' }}>
            <span>{todo.name}</span>
            <button onClick={() => handleToggleTodo(todo.id)}>Toggle</button>
            <button onClick={() => handleDeleteTodo(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default TodoList;
```
